sys_script_include.script:
var AROPCheckLibrary_INTEGRATION = Class.create();
AROPCheckLibrary_INTEGRATION.prototype = {
    initialize: function() {},
    _count: function(table, query) { var gr = new GlideRecord(table); if (query) gr.addEncodedQuery(query); gr.query(); return gr.getRowCount(); },
    _pct: function(num, den) { return den > 0 ? Math.round((num/den)*100) : 0; },
    _daysAgo: function(field, days) { var d = new GlideDateTime(); d.addDaysUTC(-days); return field + '<' + d.getValue(); },
    CHK0002107: function() {
        try {
            return (function(checkDef, dateFilter) {
    var checkPlugin = (function checkPlugin(storeScope, pluginSource) {    var result = { found: false, version: "", table: "" };    try {        var saGR = new GlideRecord("sys_store_app");        saGR.addQuery("scope", storeScope);        saGR.setLimit(1);        saGR.query();        if (saGR.next()) {            result.found = true;            result.version = saGR.getValue("version") || "";            result.table = "sys_store_app";            return result;        }    } catch(e1) {}    if (pluginSource) {        try {            var spGR = new GlideRecord("sys_plugins");            spGR.addQuery("source", pluginSource);            spGR.addQuery("active", true);            spGR.setLimit(1);            spGR.query();            if (spGR.next()) {                result.found = true;                result.version = spGR.getValue("version") || "";                result.table = "sys_plugins";                return result;            }        } catch(e2) {}    }    return result;});
    var result = checkPlugin("com.glide.hub.integration_hub", "com.glide.hub.integration_hub");
    // Functional fallback: check if sys_hub_action_type table exists
    if (!result.found) {
        var testGr = new GlideRecord("sys_hub_action_type");
        testGr.setLimit(1);
        testGr.query();
        if (testGr.isValid()) { result.found = true; result.table = "functional"; }
    }
    if (result.found) {
        return { status: "ready",
            actualValue: "Integration Hub is active | source: " + result.table,
            finding: "Integration Hub is active. AI Agents can leverage spokes for external system automation." };
    } else {
        return { status: "needs_attention",
            actualValue: "Integration Hub not found in sys_store_app or sys_plugins",
            finding: "Integration Hub not active. AI Agents cannot perform external system automation without active Integration Hub." };
    }
})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002107: ' + e.message };
        }
    },
    CHK0002108: function() {
        try {
            return (function(checkDef, dateFilter) {
    // Spokes are Store Apps with scope containing "spoke"
    var gaSpokes = new GlideAggregate("sys_store_app");
    gaSpokes.addQuery("scope", "CONTAINS", "spoke");
    gaSpokes.addAggregate("COUNT");
    gaSpokes.query();
    var count = gaSpokes.next() ? parseInt(gaSpokes.getAggregate("COUNT")) || 0 : 0;

    // Fallback: check sys_plugins name LIKE Spoke if store app returns 0
    if (count === 0) {
        var gaLegacy = new GlideAggregate("sys_plugins");
        gaLegacy.addQuery("name", "CONTAINS", "Spoke");
        gaLegacy.addQuery("active", true);
        gaLegacy.addAggregate("COUNT");
        gaLegacy.query();
        count = gaLegacy.next() ? parseInt(gaLegacy.getAggregate("COUNT")) || 0 : 0;
    }

    if (count >= 5) {
        return { status: "ready", actualValue: count + " active Integration Hub spokes",
            finding: count + " active spokes -- AI Agents have broad external automation capability." };
    } else {
        return { status: "needs_attention", actualValue: count + " active Integration Hub spokes",
            finding: "Only " + count + " active spokes. AI Agents require spokes for external system automation -- low spoke count limits AI Agent action scope." };
    }
})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002108: ' + e.message };
        }
    },
    CHK0002109: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_rest_message");gr.addQuery("active",true);gr.query();var n=gr.getRowCount();return{status:n>=10?"ready":"needs_attention",actualValue:n+" active REST message configurations",finding:n<10?"Only "+n+" active REST messages. Now Assist and AI Agents use REST for external system integration -- low count limits AI-triggered external actions.":n+" active REST messages -- good external API coverage for Now Assist AI integrations."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002109: ' + e.message };
        }
    },
    CHK0002110: function() {
        try {
            return (function(){var gr=new GlideRecord("discovery_credential");gr.addQuery("active",true);gr.query();var n=gr.getRowCount();return{status:n>=5?"ready":"needs_attention",actualValue:n+" active stored credentials",finding:n<5?"Only "+n+" active credentials in store. Missing credentials cause AI Agent external actions to fail silently.":n+" stored credentials -- AI Agents have authentication for external system access."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002110: ' + e.message };
        }
    },
    CHK0002111: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_alias");gr.addQuery("active",true);gr.query();var n=gr.getRowCount();return{status:n>=5?"ready":"needs_attention",actualValue:n+" active Flow Designer connections",finding:n<5?"Only "+n+" active Flow Designer connections. AI Agent external automation flows require healthy connection records.":n+" active connections -- Flow Designer AI Agent integrations have authenticated access."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002111: ' + e.message };
        }
    },
    CHK0002112: function() {
        try {
            return (function(){var gr=new GlideRecord("ecc_agent");gr.addQuery("status","Up");gr.query();var up=gr.getRowCount();var gr2=new GlideRecord("ecc_agent");gr2.query();var total=gr2.getRowCount();return{status:up>=1?"ready":"needs_attention",actualValue:total+" MID Servers | "+up+" Up",finding:up<1?"No MID Servers Up. AI Agent on-premise integrations require available MID Servers.":up+" MID Servers Up -- AI Agents can reach on-premise systems via MID Server."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002112: ' + e.message };
        }
    },
    CHK0002113: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_hub_flow");gr.addQuery("active",true);gr.addEncodedQuery("trigger_typeLIKErecord^ORtrigger_typeLIKEschedule");gr.query();var n=gr.getRowCount();return{status:n>=10?"ready":"needs_attention",actualValue:n+" event-triggered Flow Designer flows",finding:n<10?"Only "+n+" event-triggered flows. Now Assist AI Agents benefit from event-driven patterns for real-time response to external system changes.":n+" event-triggered flows -- AI Agents can respond to real-time external events."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002113: ' + e.message };
        }
    },
    CHK0002114: function() {
        try {
            return (function(){var gr=new GlideRecord("ecc_queue");gr.addQuery("state","error");gr.query();var errors=gr.getRowCount();var gr2=new GlideRecord("ecc_queue");gr2.query();var total=gr2.getRowCount();var pct=total>0?Math.round((errors/total)*100):0;return{status:pct<=5?"ready":"needs_attention",actualValue:pct+"% integration queue errors ("+errors+"/"+total+")",finding:pct>5?errors+" integration queue items in error ("+pct+"%). High error rates cause AI Agent external actions to fail silently.":"Integration error rate of "+pct+"% is acceptable -- AI Agent external actions can execute reliably."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002114: ' + e.message };
        }
    },
    CHK0002115: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_rest_message");gr.addQuery("active",true);gr.query();var n=gr.getRowCount();return{status:n>=5?"ready":"needs_attention",actualValue:n+" active REST integrations to review for rate limits",finding:""+n+" active REST integrations. Review each for rate limit configuration -- AI Agent automation can generate high API request volumes that trigger rate limit throttling without proper configuration."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002115: ' + e.message };
        }
    },
    CHK0002116: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_rest_message_fn");gr.addQuery("active",true);gr.addQuery("http_method","POST");gr.query();var n=gr.getRowCount();return{status:n>=5?"ready":"needs_attention",actualValue:n+" active outbound REST function endpoints",finding:n<5?"Only "+n+" outbound REST endpoints. AI Agent notification and update actions require configured outbound webhooks for external system delivery.":n+" outbound REST endpoints -- AI Agent notifications can reach external systems."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002116: ' + e.message };
        }
    },
    CHK0002117: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_properties");gr.addQuery("name","com.glide.hub.flow_engine.log_level");gr.setLimit(1);gr.query();var level=gr.next()?gr.getValue("value"):"not set";var adequate=(level==="debug"||level==="info"||level==="warn");return{status:adequate?"ready":"needs_attention",actualValue:"Integration Hub log level: "+level,finding:adequate?"Integration Hub logging is active at level "+level+" -- AI Agent external actions are auditable.":"Integration Hub log level is "+level+". Enable logging to audit AI Agent external action results."};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002117: ' + e.message };
        }
    },
    CHK0002118: function() {
        try {
            return (function(){var gr=new GlideRecord("sys_script");gr.addEncodedQuery("collectionINecc_queue,sys_rest_message^active=true^sys_created_byNOT INglide.maint,system,admin,fred.luddy");gr.query();var n=gr.getRowCount();return{status:n<=5?"ready":"needs_attention",actualValue:n+" custom BRs on integration tables",finding:"Integration customization risk: "+n+" custom BRs. "+(n>5?"Custom BRs on integration tables can intercept Now Assist AI Agent integration flows.":"Risk within acceptable range for Now Assist AI Agent integrations.")};})();
        } catch(e) {
            return { status: 'needs_attention', actualValue: 'Script error: ' + e.message, finding: 'Error in CHK0002118: ' + e.message };
        }
    },
    type: 'AROPCheckLibrary_INTEGRATION'
};
